(async () => {
  const lines = [];
  lines.push("PAGES: " + figma.root.children.map(p => p.id + ":" + p.name).join(" | "));
  const ws = figma.root.children.find(p => p.id === "11:2");
  lines.push("WS children: " + ws.children.length);
  let fontMsg = "";
  try { await figma.loadFontAsync({ family: "Source Sans Pro", style: "Bold" }); fontMsg = "OK"; }
  catch (e) { fontMsg = "FAIL " + e.message; }
  lines.push("FONT SourceSansPro: " + fontMsg);

  const insp = [];
  for (const id of ["9:27","9:49","9:25","9:50","9:31","9:26","9:3","9:55"]) {
    const n = figma.getNodeById(id);
    if (!n) { insp.push(id + " MISSING"); continue; }
    const walk = (node, depth) => {
      if (depth > 3) return node.type + ":" + node.name;
      const o = node.type + " '" + node.name + "'";
      if ('fills' in node && node.fills && node.fills.length) {
        o += " fills=" + node.fills.map(f => f.type + (f.imageHash ? "#" + String(f.imageHash).slice(0,6) : "")).join(",");
      }
      if ('characters' in node) o += ' text="' + node.characters.slice(0,20) + '"';
      if ('children' in node) o += " [" + node.children.slice(0,8).map(c => walk(c, depth + 1)).join(" ; ") + "]";
      return o;
    };
    insp.push(id + " " + walk(n, 0));
  }
  lines.push("INSPECT:");
  lines.push(...insp);
  figma.notify("inspect done");
  return lines.join("\n");
})();

